sys_script.script:
(function(current, previous) {
    var val = current.getValue('report_number');
    if (val && ('' + val).trim() !== '') return;

    var parentRef = current.getValue('procurement_order');
    var parentNumber = '';

    if (parentRef) {
        var parentGr = new GlideRecord('x_2056099_indust_0_proc_order');
        if (parentGr.get(parentRef)) {
            parentNumber = '' + parentGr.getValue('number');
        }
    }

    if (parentNumber) {
        var itemPrefix = parentNumber + '-RPT-';

        var ga = new GlideAggregate('x_2056099_indust_0_proc_rpt');
        ga.addQuery('procurement_order', parentRef);
        ga.addAggregate('COUNT');
        ga.query();
        var count = 0;
        if (ga.next()) {
            count = parseInt(ga.getAggregate('COUNT'), 10);
        }

        var gr = new GlideRecord('x_2056099_indust_0_proc_rpt');
        gr.addQuery('report_number', 'STARTSWITH', itemPrefix);
        gr.query();
        var maxSeq = 0;
        while (gr.next()) {
            var numVal = '' + gr.getValue('report_number');
            var parts = numVal.split('-');
            var lastPart = parts[parts.length - 1];
            var num = parseInt(lastPart, 10);
            if (!isNaN(num) && num > maxSeq) maxSeq = num;
        }

        var nextSeq = count + 1;
        if (nextSeq <= maxSeq) nextSeq = maxSeq + 1;

        var pad = '' + nextSeq;
        while (pad.length < 3) pad = '0' + pad;
        var candidate = itemPrefix + pad;

        var check = new GlideRecord('x_2056099_indust_0_proc_rpt');
        check.addQuery('report_number', candidate);
        check.setLimit(1);
        check.query();
        while (check.hasNext()) {
            check.next();
            nextSeq++;
            pad = '' + nextSeq;
            while (pad.length < 3) pad = '0' + pad;
            candidate = itemPrefix + pad;
            check = new GlideRecord('x_2056099_indust_0_proc_rpt');
            check.addQuery('report_number', candidate);
            check.setLimit(1);
            check.query();
        }

        current.setValue('report_number', candidate);
    } else {
        var gen = new AutoNumberGenerator();
        current.setValue('report_number', gen.generate('x_2056099_indust_0_proc_rpt', 'report_number', 'RPT', 3, true));
    }
})(current, previous);
